# 生产部署用（2C2G 精简模式）
# - 去掉 Prometheus，指标改用阿里云云监控 / 按需临时启动
# - 数据库与 Redis 不发布任何宿主机端口，仅容器网络内访问
# - api 只绑定 127.0.0.1，由宿主机/前置 Nginx 反代对外
# - 所有服务设置内存上限，避免单服务失控拖垮整机
# - 迁移作为一次性任务先跑，成功后 api/worker 才启动

services:
  postgres:
    image: postgres:16-alpine
    restart: unless-stopped
    environment:
      POSTGRES_USER: ${POSTGRES_USER}
      POSTGRES_PASSWORD: ${POSTGRES_PASSWORD}
      POSTGRES_DB: ${POSTGRES_DB}
    command:
      - postgres
      - -c
      - shared_buffers=64MB
      - -c
      - max_connections=20
      - -c
      - work_mem=2MB
      - -c
      - maintenance_work_mem=32MB
      - -c
      - effective_cache_size=256MB
    volumes:
      - pgdata:/var/lib/postgresql/data
    mem_limit: 512m
    healthcheck:
      test: ["CMD-SHELL", "pg_isready -U ${POSTGRES_USER} -d ${POSTGRES_DB}"]
      interval: 10s
      timeout: 3s
      retries: 10
      start_period: 20s

  redis:
    image: redis:7-alpine
    restart: unless-stopped
    command:
      - redis-server
      - --maxmemory
      - 32mb
      - --maxmemory-policy
      - allkeys-lru
      - --save
      - ""
    mem_limit: 128m
    healthcheck:
      test: ["CMD", "redis-cli", "ping"]
      interval: 10s
      timeout: 3s
      retries: 10

  migrate:
    image: openquizgo:local
    restart: "no"
    env_file: .env
    # 镜像 ENTRYPOINT 是 /app/api，这里必须显式覆盖，否则跑的是 API
    entrypoint: ["/app/migrate"]
    command: ["up"]
    mem_limit: 256m
    security_opt:
      - no-new-privileges:true
    volumes:
      - quizdata:/app/data
    depends_on:
      postgres:
        condition: service_healthy
      redis:
        condition: service_healthy

  api:
    image: openquizgo:local
    build:
      context: .
      args:
        GOPROXY: https://goproxy.cn,direct
    restart: unless-stopped
    env_file: .env
    mem_limit: 256m
    security_opt:
      - no-new-privileges:true
    ports:
      - "127.0.0.1:8080:8080"
    volumes:
      - quizdata:/app/data
    depends_on:
      migrate:
        condition: service_completed_successfully
    healthcheck:
      test: ["CMD", "wget", "-qO-", "http://127.0.0.1:8080/healthz"]
      interval: 15s
      timeout: 3s
      retries: 5
      start_period: 10s

  worker:
    image: openquizgo:local
    restart: unless-stopped
    env_file: .env
    entrypoint: ["/app/worker"]
    mem_limit: 128m
    security_opt:
      - no-new-privileges:true
    volumes:
      - quizdata:/app/data
    depends_on:
      migrate:
        condition: service_completed_successfully

  # Atlas 静态站 + QuizGo 管理后台/API 反代
  # 一条 nginx 同时服务两个项目，比两个容器省 20–30MB
  web:
    image: nginx:1.27-alpine
    restart: unless-stopped
    mem_limit: 64m
    # host 网络：nginx 能看到真实客户端 IP，allow/deny 才生效；
    # 也不经 docker-proxy，access log 里是真实来源
    network_mode: host
    volumes:
      - /srv/atlas:/srv/atlas:ro
      - /srv/quizgo/admin-web/dist:/srv/quizgo/admin-web/dist:ro
      - /srv/nginx/nginx.conf:/etc/nginx/nginx.conf:ro
      - /srv/nginx/conf.d:/etc/nginx/conf.d:ro
    depends_on:
      api:
        condition: service_healthy

volumes:
  pgdata:
  quizdata:
=== quiz.conf
# OpenQuizGo 管理后台 + API
# 测试期：127.0.0.1:8082（SSH 隧道访问）
# 备案通过后：改成 listen 80 / 443，server_name quiz.openapp.asia
server {
    listen 8082;
    # 只允许本机与 Tailscale 网段（100.64.0.0/10），其余一律拒绝
    allow 127.0.0.1;
    allow 100.64.0.0/10;
    deny  all;
    server_name quiz.openapp.asia;

    root  /srv/quizgo/admin-web/dist;
    index index.html;

    add_header X-Content-Type-Options nosniff always;
    add_header Referrer-Policy strict-origin-when-cross-origin always;
    add_header X-Frame-Options SAMEORIGIN always;
    add_header Content-Security-Policy "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; font-src 'self' data:; connect-src 'self'; object-src 'none'; base-uri 'self'" always;

    # 指标不对公网开放
    location /metrics {
        deny all;
    }

    # API 反代到 quizgo api 容器
    location /v1/ {
        proxy_pass http://127.0.0.1:8080$request_uri;
        proxy_http_version 1.1;
        proxy_set_header Host              $host;
        proxy_set_header X-Real-IP         $remote_addr;
        proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_read_timeout 30s;
        proxy_send_timeout 30s;
    }

    location = /healthz {
        proxy_pass http://127.0.0.1:8080/healthz;
        access_log off;
    }

    # 带 hash 的资源长缓存
    location /assets/ {
        add_header Cache-Control "public, max-age=31536000, immutable";
        try_files $uri =404;
    }

    location = /index.html {
        add_header Cache-Control "no-cache";
    }

    # 管理后台是 SPA，刷新子路由要回退到 index.html
    location / {
        try_files $uri $uri/ /index.html;
    }
}
=== nginx.conf
worker_processes 1;
error_log /dev/stderr warn;
pid /var/run/nginx.pid;

events {
    worker_connections 1024;
}

http {
    include       /etc/nginx/mime.types;
    default_type  application/octet-stream;

    log_format main '$remote_addr - $remote_user [$time_local] "$request" '
                    '$status $body_bytes_sent "$http_referer" '
                    '"$http_user_agent" rt=$request_time';
    access_log /dev/stdout main;

    sendfile           on;
    tcp_nopush         on;
    keepalive_timeout  65;
    server_tokens      off;

    # 3Mbps 带宽下必须开 gzip
    gzip              on;
    gzip_vary         on;
    gzip_comp_level   5;
    gzip_min_length   1024;
    gzip_proxied      any;
    gzip_types        text/plain text/css application/javascript application/json
                      application/manifest+json image/svg+xml application/xml;

    # 题目图片上传上限
    client_max_body_size 8m;

    include /etc/nginx/conf.d/*.conf;
}

